                         .receiverQueueSize(100)
                         .messageListener((consumer, msg) -> {
                             try {
                                 if (slowKey.equals(msg.getKey())) {
                                     // Block the thread to simulate a slow consumer
                                     Thread.sleep(10000);
                                 }
                                 receivedMessages.incrementAndGet();
                                 consumer.acknowledge(msg);
                             } catch (Exception e) {
                                 e.printStackTrace();
                             }
