-            shouldRewindBeforeReadingOrReplaying = false;
-            readMoreEntries();
-            return;
-        }
-
-        log.debug()
-                .attr("entryCount", entries.size())
-                .attr("consumerCount", consumerList.size())
-                .log("Distributing messages to consumers");
